INSERT INTO `v1_3715ca5077f41f74b41d6bef4742a28252ab60ab8bd6c32f9215642f81756ae9` VALUES ("bgm_M199", "", 1002, "2020-02-15 15:00:00", "愛情たっぷりのチョコレートケー\nキを完成させよう！\n超キュートなタップゲーム！", "bgm_M199_juke", 1001, "お兄ちゃん争奪！\nどっちのチョコがおいしいでSHOW", 10000, "2030/12/31 15:00:00", "2030/12/31 15:00:00");
INSERT INTO `v1_3715ca5077f41f74b41d6bef4742a28252ab60ab8bd6c32f9215642f81756ae9` VALUES ("bgm_M227", "", 1003, "2020-02-15 15:00:00", "大回転！クウカ！\n最高のエクスタシーここにあり！\n引っ張って飛ばす、空の旅！", "bgm_M227_juke", 1002, "クウカ大回転\n飛行道中エクスタシー", 10000, "2030/12/31 15:00:00", "2030/12/31 15:00:00");
