INSERT INTO `v1_3715ca5077f41f74b41d6bef4742a28252ab60ab8bd6c32f9215642f81756ae9` VALUES ("bgm_M277", "", 1005, "2020-02-15 15:00:00", "白熱バトル！\nドラゴンズネスト流\nタイマン式頭脳しりとり！", "bgm_M277_juke", 1004, "大激戦！しりとりドラゴンズ", 10000, "2030/12/31 15:00:00", "2030/12/31 15:00:00");
INSERT INTO `v1_3715ca5077f41f74b41d6bef4742a28252ab60ab8bd6c32f9215642f81756ae9` VALUES ("bgm_M355_Lofi", "", 1006, "2020-05-31 12:00:00", "キミはチーズを守り抜けるか！？\n瞬発力が試される\n反射神経系カジュアルゲーム！", "bgm_M355_Lofi_juke", 1005, "チュウチュウパニック！\nチーズお守り大作戦！", 10000, "2030/12/31 15:00:00", "2030/12/31 15:00:00");
