INSERT INTO `v1_3715ca5077f41f74b41d6bef4742a28252ab60ab8bd6c32f9215642f81756ae9` VALUES ("bgm_M540", "", 1009, "2021-12-18 15:00:00", "レッツ・クッキング！\nミヤコとプリンを作って食べて\nプリンの道を極めよう！", "bgm_M540", 1008, "ミヤコ's キッチン　究極への道", 10000, "2030/12/31 15:00:00", "2030/12/31 15:00:00");
INSERT INTO `v1_3715ca5077f41f74b41d6bef4742a28252ab60ab8bd6c32f9215642f81756ae9` VALUES ("bgm_M569", "ランドソルクイズコネクト！", 1010, "2022-02-15 15:00:00", "５人チームで力を合わせて多種多\n様なジャンルのクイズに挑戦！\n目指せ、クイズプリンセス！", "bgm_M569", 1009, "Happy Anniv.スペシャル　\nランドソルクイズコネクト！", 0, "2022/02/28 11:59:59", "2022/02/15 15:00:00");
