INSERT INTO `v1_3715ca5077f41f74b41d6bef4742a28252ab60ab8bd6c32f9215642f81756ae9` VALUES ("bgm_MC068", "放課後クイズエデュケーション　{0}", 1012, "2023-09-18 15:00:00", "めざせ全問正解！\nキャルとスズナと放課後の教室で\n二人きりのクイズ勉強会！", "bgm_MC068", 1012, "キャルとスズナの\n放課後クイズエデュケーション", 10000, "2030/12/31 15:00:00", "2030/12/31 15:00:00");
INSERT INTO `v1_3715ca5077f41f74b41d6bef4742a28252ab60ab8bd6c32f9215642f81756ae9` VALUES ("bgm_MC141", "行軍（マーチ）A-Go-Go！", 1013, "2024-04-18 15:00:00", "魔物はびこる街道を突き進め！\n【王宮騎士団(NIGHTMARE)】\nの兵たちを率い、訓練に挑戦だ！", "bgm_MC141", 1013, "エリコとマコトの\n行軍（マーチ）A-Go-Go！", 10000, "2030/12/31 15:00:00", "2030/12/31 15:00:00");
